        Func<TParam1, TParam2, TParam3, TParam4, TParam5, TParam6, TParam7, TParam8, TParam9, TParam10, TParam11, TParam12, TParam13, TParam14, TParam15, bool>? canExecute = null,
        int semaphore = 1)
        : base(
            command is null ? throw new System.ArgumentNullException(nameof(command)) : (parameter, ct) => command(parameter.Item1, parameter.Item2, parameter.Item3, parameter.Item4, parameter.Item5, parameter.Item6, parameter.Item7, parameter.Item8, parameter.Item9, parameter.Item10, parameter.Item11, parameter.Item12, parameter.Item13, parameter.Item14, parameter.Item15, ct),
