            canExecute is null ? null : parameter => canExecute(parameter.Item1, parameter.Item2, parameter.Item3, parameter.Item4, parameter.Item5, parameter.Item6, parameter.Item7, parameter.Item8, parameter.Item9, parameter.Item10, parameter.Item11, parameter.Item12, parameter.Item13, parameter.Item14, parameter.Item15),
            semaphore,
