        Func<TParam1, TParam2, TParam3, TParam4, TParam5, TParam6, TParam7, TParam8, TParam9, TParam10, TParam11, TParam12, TParam13, TParam14, TParam15, bool>? canExecute = null,
        int semaphore = 1)
    {
        if (command is null)
        {
            throw new System.ArgumentNullException(nameof(command));
